<?php if ($canInput): ?><div class="tab-pane fade" id="buat"><form method="post" action="<?= site_url('poHabisPakai/simpan') ?>"><?= csrf_field() ?><div class="form-row"><div class="form-group col-md-3"><label>Tanggal PO</label><input type="date" name="tanggal_po" class="form-control" value="<?= date('Y-m-d') ?>" required></div><div class="form-group col-md-5"><label>Supplier/Vendor</label><select name="supplier_id" class="form-control" required><option value="">-- pilih --</option><?php foreach ($suppliers as $s): ?><option value="<?= $s['supid'] ?>"><?= esc($s['supnama']) ?></option><?php endforeach; ?></select></div><div class="form-group col-md-4"><label>Catatan</label><input name="catatan" class="form-control"></div></div><table class="table table-bordered"><thead><tr><th>Barang</th><th>Satuan</th><th>Qty Pesan</th><th>Harga</th></tr></thead><tbody><?php foreach ($stok as $s): ?><tr><td><?= esc($s['nama']) ?><input type="hidden" name="stok_id[]" value="<?= $s['id'] ?>"></td><td><?= esc($s['satuan']) ?></td><td><input type="number" name="qty_pesan[]" class="form-control" min="0" step="0.001" value="0"></td><td><input type="number" name="harga[]" class="form-control" min="0" step="0.01" value="0"></td></tr><?php endforeach; ?></tbody></table><button class="btn btn-primary">Simpan PO Barang Habis Pakai</button></form></div><?php endif; ?>
