= number_format((float)$r['qty'], 3, ',', '.') ?></td><td><?= esc($r['diterima_at']) ?></td><td><button type="button" class="btn btn-sm btn-warning" data-toggle="modal" data-target="#editTerima<?= $r['id'] ?>">Edit</button><form method="post" action="<?= site_url('poHabisPakai/hapusPenerimaan/' . $r['id']) ?>" class="d-inline" data-bootstrap-confirm="Hapus penerimaan ini dan kurangi stok?"><?= csrf_field() ?><button class="btn btn-sm btn-danger">Hapus</button></form></td></tr><div class="modal fade" id="editTerima<?= $r['id'] ?>"><div class="modal-dialog"><div class="modal-content"><form method="post" action="<?= site_url('poHabisPakai/updatePenerimaan/' . $r['id']) ?>"><?= csrf_field() ?><div class="modal-header"><h5>Edit Penerimaan</h5><button type="button" class="close" data-dismiss="modal">&times;</button></div><div class="modal-body"><label>Qty</label><input type="number" name="qty" class="form-control" min="0.001" step="0.001" value="<?= (float)$r['qty'] ?>" required><label>Invoice</label><input name="nomor_invoice" class="form-control" value="<?= esc($r['nomor_invoice']) ?>" required><label>Surat Jalan</label><input name="nomor_surat_jalan" class="form-control" value="<?= esc($r['nomor_surat_jalan'] ?? '') ?>"></div><div class="modal-footer"><button class="btn btn-primary">Simpan Perubahan</button></div></form></div></div></div><?php endforeach; ?></tbody></table></div><?php endif; ?></div></div></div>
